94	// ---- 磁盘结构（JSON，版本仍为 1） ----
95	
96	type storedMember struct {
97		ID     string `json:"id"`
98		Weight int64  `json:"weight"`
99	}
100	
101	type storedDelegation struct {
102		From string `json:"from"`
103		To   string `json:"to"`
104	}
105	
106	// storedBallot 是一张已保存的票。四个字段都必须明确写出、非空且类型正确：
107	// representative 是 JSON 字符串，weight/voted_at 是 JSON 整数（int64 范围），
108	// support 必须是 JSON 布尔值。绝不能靠零值/默认值补出治理记录：
109	// 缺失或 null 的 support 不得被当作 false（反对票），缺失或 null 的
110	// voted_at 不得被当作 0（首次投票时间）。
111	//
112	// 标量字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
113	// 仍可区分：encoding/json 直接解进 bool/int64/string 时会把这三种情况都
114	// 折叠成零值。每个字段的“缺失/空值/类型不符”由 validateStoredBallot 判定。
115	type storedBallot struct {
116		Representative string `json:"representative"`
117		Weight         int64  `json:"weight"`
118		Support        bool   `json:"support"`
119		VotedAt        int64  `json:"voted_at"`
120	
121		representativeRaw json.RawMessage
122		weightRaw         json.RawMessage
123		supportRaw        json.RawMessage
124		votedAtRaw        json.RawMessage
125	}
126	
127	// ballotJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
128	type ballotJSONShape struct {
129		Representative json.RawMessage `json:"representative"`
130		Weight         json.RawMessage `json:"weight"`
131		Support        json.RawMessage `json:"support"`
132		VotedAt        json.RawMessage `json:"voted_at"`
133	}
134	
135	// UnmarshalJSON 保留字段是否出现及其原始写法（缺失为 nil、null 为 "null"），
136	// 供 validateStoredBallot 区分缺失、空值与类型不符。单个字段类型不符时这里
137	// 不返回错误（对应治理字段保持零值），以免解码器在不含提案编号/票据下标的
138	// 通用错误处提前失败；定位与判定统一交给 validateStoredBallot。
139	func (b *storedBallot) UnmarshalJSON(data []byte) error {
140		var shape ballotJSONShape
141		if err := json.Unmarshal(data, &shape); err != nil {
142			return err
143		}
144		b.representativeRaw, b.weightRaw = shape.Representative, shape.Weight
145		b.supportRaw, b.votedAtRaw = shape.Support, shape.VotedAt
146		// 仅当字段确实是目标类型时才填充治理字段；类型不符留待校验拒绝，
147		// 绝不能让错误类型悄悄落成零值并参与查询或计票。
148		if raw := shape.Representative; jsonValueType(raw) == "string" {
149			_ = json.Unmarshal(raw, &b.Representative)
150		}
151		if raw := shape.Weight; isInt64Number(raw) {
152			_ = json.Unmarshal(raw, &b.Weight)
153		}
154		if raw := shape.Support; jsonValueType(raw) == "boolean" {
155			_ = json.Unmarshal(raw, &b.Support)
156		}
157		if raw := shape.VotedAt; isInt64Number(raw) {
158			_ = json.Unmarshal(raw, &b.VotedAt)
159		}
160		return nil
161	}
162	
163	// MarshalJSON 只输出四个治理字段，RawMessage 状态（仅用于入站判定）不落盘。
164	func (b storedBallot) MarshalJSON() ([]byte, error) {
165		return json.Marshal(storedBallotOut{
166			Representative: b.Representative,
167			Weight:         b.Weight,
168			Support:        b.Support,
169			VotedAt:        b.VotedAt,
170		})
171	}
172	
173	// storedBallotOut 是票据的保存形状；字段名与保存格式逐字一致。
174	type storedBallotOut struct {
175		Representative string `json:"representative"`
176		Weight         int64  `json:"weight"`
177		Support        bool   `json:"support"`
178		VotedAt        int64  `json:"voted_at"`
179	}
180	
181	// mustStoreBallot 构造一张内存中的合法票据（投票成功路径使用）。
182	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
183	// validateStoredBallot 判定时不会把本进程新建的票据误判为字段缺失。
184	func mustStoreBallot(representative string, weight int64, support bool, votedAt int64) storedBallot {
185		repRaw, _ := json.Marshal(representative)
186		wRaw, _ := json.Marshal(weight)
187		supRaw, _ := json.Marshal(support)
188		atRaw, _ := json.Marshal(votedAt)
189		return storedBallot{
190			Representative:    representative,
191			Weight:            weight,
192			Support:           support,
193			VotedAt:           votedAt,
194			representativeRaw: repRaw,
195			weightRaw:         wRaw,
196			supportRaw:        supRaw,
197			votedAtRaw:        atRaw,
198		}
199	}
200	
201	// validateStoredBallot 严格判定一张已保存票据的四个必填字段：
202	// 任一字段未写出、显式为 null 或 JSON 类型不符（support 不接受字符串/数字，
203	// weight/voted_at 不接受字符串/小数/指数等非整数）都返回带原因的错误。
204	// 明确写出的 false 是有效反对票；窗口允许时明确写出的 0 是有效投票时间，
205	// 这两种合法值不得当成缺失。index 是票据在提案中的下标（0 起），用于定位。
206	func validateStoredBallot(id string, index int, b *storedBallot) error {
207		check := func(field string, raw json.RawMessage, kind string, decode func() error) error {
208			switch {
209			case raw == nil:
210				return fmt.Errorf("voting proposal %q ballot %d field %q is missing", id, index, field)
211			case string(raw) == "null":
212				return fmt.Errorf("voting proposal %q ballot %d field %q is null", id, index, field)
213			default:
214				if err := decode(); err != nil {
215					return fmt.Errorf("voting proposal %q ballot %d field %q has wrong type: want %s, got %s",
216						id, index, field, kind, jsonValueType(raw))
217				}
218				return nil
219			}
220		}
221		if err := check("representative", b.representativeRaw, "string", func() error {
222			return json.Unmarshal(b.representativeRaw, new(string))
223		}); err != nil {
224			return err
225		}
226		if err := check("weight", b.weightRaw, "integer", func() error {
227			return json.Unmarshal(b.weightRaw, new(int64))
228		}); err != nil {
229			return err
230		}
231		if err := check("support", b.supportRaw, "boolean", func() error {
232			return json.Unmarshal(b.supportRaw, new(bool))
233		}); err != nil {
234			return err
235		}
236		if err := check("voted_at", b.votedAtRaw, "integer", func() error {
237			return json.Unmarshal(b.votedAtRaw, new(int64))
238		}); err != nil {
239			return err
240		}
241		return nil
242	}
243	
244	// jsonValueType 按字段实际写出 JSON 的首字节归类其 JSON 类型。
245	// RawMessage 是从合法 JSON 文档中取出的单个值，首字节足以区分
246	// 字符串/布尔/null/数字/数组/对象，无需再次解码。
247	func jsonValueType(raw json.RawMessage) string {
248		for _, c := range raw {
249			switch c {
250			case ' ', '\t', '\n', '\r':
251				continue
252			case '"':
253				return "string"
254			case 't', 'f':
255				return "boolean"
256			case 'n':
257				return "null"
258			case '[':
259				return "array"
260			case '{':
261				return "object"
262			default:
263				return "number"
264			}
265		}
266		return "invalid json"
267	}
268	
269	// isInt64Number 判断原始 JSON 是否为落在有符号 64 位整数范围内的整数字面量：
270	// 必须是 JSON 数字（首字节为数字或 '-'），且能被 ParseInt 以 10 进制精确解析。
271	// 小数、指数、超界整数均返回 false。
272	func isInt64Number(raw json.RawMessage) bool {
273		if jsonValueType(raw) != "number" {
274			return false
275		}
276		_, err := strconv.ParseInt(strings.TrimSpace(string(raw)), 10, 64)
277		return err == nil
278	}
279	
280	type storedTally struct {
281		ForWeight     int64 `json:"for_weight"`
282		AgainstWeight int64 `json:"against_weight"`
283		TalliedAt     int64 `json:"tallied_at"`
284	}
285	
286	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
287	// 动作文本与顺序原样保存（顺序影响相等性）。
288	type storedVoteProposal struct {
289		ID          string             `json:"id"`
290		State       string             `json:"state"`
291		Members     []storedMember     `json:"members"`
292		Delegations []storedDelegation `json:"delegations"`
293		Quorum      int64              `json:"quorum"`
294		StartAt     int64              `json:"start_at"`
295		Deadline    int64              `json:"deadline"`
296		TimelockEnd int64              `json:"timelock_end"`
297		Actions     []string           `json:"actions"`
298		Ballots     []storedBallot     `json:"ballots"`
299		Tally       *storedTally       `json:"tally,omitempty"`
300	}
301	
302	// ---- 校验与派生 ----
303	
304	type proposalSpec struct {
305		members  []VoteMember
306		weights  map[string]int64
307		delegate map[string]string // 直接委托对象
308		pathOf   map[string][]string
309		headOf   map[string]string // 最终代表
310		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
311		total    int64
312	}
313	
314	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
315	// 任何非法条件都返回错误，调用方必须整项拒绝。
316	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
317		if in.ID == "" {
318			return nil, invalidProposal("proposal id must not be empty")
319		}
320		if len(in.Members) == 0 {
321			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
322		}
323		weights := make(map[string]int64, len(in.Members))
324		order := make([]string, 0, len(in.Members))
325		for _, m := range in.Members {
326			if m.ID == "" {
327				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
328			}
329			if _, dup := weights[m.ID]; dup {
330				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
331			}
332			if m.Weight <= 0 {
333				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
334			}
335			weights[m.ID] = m.Weight
336			order = append(order, m.ID)
337		}
338	
339		// 总权重必须在 int64 范围内（各权重已为正）。
340		var total int64
341		for _, m := range in.Members {
342			sum, ok := addInt64(total, m.Weight)
343			if !ok {
344				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
345			}
346			total = sum
347		}
348	
349		if in.Quorum < 1 || in.Quorum > total {
350			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
351		}
352		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
353			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
354				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
355		}
356	
357		delegate := make(map[string]string, len(in.Delegations))
358		for _, d := range in.Delegations {
359			if d.From == "" || d.To == "" {
360				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
361			}
362			if _, ok := weights[d.From]; !ok {
363				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
364			}
365			if _, ok := weights[d.To]; !ok {
366				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
367			}
368			if d.From == d.To {
369				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
370			}
371			if _, dup := delegate[d.From]; dup {
372				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
373			}
374			delegate[d.From] = d.To
375		}
376	
377		// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
378		// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
379		// 所以该遍历必然终止。
380		// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
381		// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
382		// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
383		pathOf := make(map[string][]string, len(weights))
384		headOf := make(map[string]string, len(weights))
385		for _, id := range order {
386			if _, done := headOf[id]; done {
387				continue
388			}
389			chain := []string{id}
390			onChain := map[string]int{id: 0}
391			cur := id
392			for {
393				next, has := delegate[cur]
394				if !has {
395					break // cur 即未再委托的最终代表
396				}
397				if pos, cyc := onChain[next]; cyc {
398					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
399				}
400				if resolved, ok := pathOf[next]; ok {
401					// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
402					chain = append(chain, resolved...)
403					cur = resolved[len(resolved)-1]
404					break
405				}
406				chain = append(chain, next)
407				onChain[next] = len(chain) - 1
408				cur = next
409			}
410			head := cur
411			// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
412			// 后缀成员均已登记，这里只补齐尚未解析的成员。
413			for i := 0; i < len(chain); i++ {
414				member := chain[i]
415				if _, ok := headOf[member]; !ok {
416					pathOf[member] = append([]string(nil), chain[i:]...)
417					headOf[member] = head
418				}
419			}
420		}
421	
422		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
423		groupW := make(map[string]int64)
424		for _, id := range order {
425			head := headOf[id]
426			sum, ok := addInt64(groupW[head], weights[id])
427			if !ok {
428				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
429			}
430			groupW[head] = sum
431		}
432	
433		return &proposalSpec{
434			members:  append([]VoteMember(nil), in.Members...),
435			weights:  weights,
436			delegate: delegate,
437			pathOf:   pathOf,
438			headOf:   headOf,
439			groupW:   groupW,
440			total:    total,
441		}, nil
442	}
443	
444	func invalidProposal(format string, args ...any) error {
445		return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
446	}
447	
448	// proposalsEqual 判断重试内容是否与已存提案逐项相同。
449	// 成员与委托的输入次序不影响比较；动作文本与顺序必须一致。
450	func proposalsEqual(stored *storedVoteProposal, in *CreateVoteInput, spec *proposalSpec) bool {
451		if stored.Quorum != in.Quorum || stored.StartAt != in.StartAt ||
452			stored.Deadline != in.Deadline || stored.TimelockEnd != in.TimelockEnd {
453			return false
454		}
455		if !sameActions(stored.Actions, in.Actions) {
456			return false
457		}
458		if len(stored.Members) != len(in.Members) {
459			return false
460		}
461		for _, m := range stored.Members {
462			if w, ok := spec.weights[m.ID]; !ok || w != m.Weight {
463				return false
464			}
465		}
466		if len(stored.Delegations) != len(in.Delegations) {
467			return false
468		}
469		for _, d := range stored.Delegations {
470			to, ok := spec.delegate[d.From]
471			if !ok || to != d.To {
472				return false
473			}
474		}
475		return true
476	}
