478	// ---- 存储操作 ----
479	
480	// CreateVoteProposal 创建一项投票提案。
481	// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
482	// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
483	// 非法条件整项拒绝，不落盘任何部分变化。
484	func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
485		spec, err := validateProposalInput(in)
486		if err != nil {
487			return nil, false, err
488		}
489		commit, err := s.begin()
490		if err != nil {
491			return nil, false, err
492		}
493		defer commit()
494	
495		state, err := s.loadLocked()
496		if err != nil {
497			return nil, false, err
498		}
499		if existing, ok := state.VoteProposals[in.ID]; ok {
500			if !proposalsEqual(existing, in, spec) {
501				return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
502			}
503			v := voteProposalView(existing)
504			return v, true, nil
505		}
506		if _, ok := state.Proposals[in.ID]; ok {
507			// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
508			return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
509		}
510	
511		stored := &storedVoteProposal{
512			ID:          in.ID,
513			State:       "voting",
514			Members:     make([]storedMember, 0, len(in.Members)),
515			Delegations: make([]storedDelegation, 0, len(in.Delegations)),
516			Quorum:      in.Quorum,
517			StartAt:     in.StartAt,
518			Deadline:    in.Deadline,
519			TimelockEnd: in.TimelockEnd,
520			Actions:     copyActions(in.Actions),
521			Ballots:     []storedBallot{},
522		}
523		for _, m := range in.Members {
524			stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
525		}
526		for _, d := range in.Delegations {
527			stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
528		}
529		state.VoteProposals[in.ID] = stored
530		if err := s.commitLocked(state); err != nil {
531			return nil, false, err
532		}
533		return voteProposalView(stored), false, nil
534	}
