536	func voteReject(reason string) error {
537		return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
538	}
539	
540	func tallyReject(reason string) error {
541		return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
542	}
543	
544	// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----
545	
546	// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
547	// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
548	// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
549	type ballotCounts struct {
550		forWeight     int64
551		againstWeight int64
552	}
553	
554	// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
555	// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
556	// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
557	func (c ballotCounts) turnout() (int64, bool) {
558		return addInt64(c.forWeight, c.againstWeight)
559	}
560	
561	// votePasses 是唯一的通过条件：参与权重达到法定人数（恰好达到也算）
562	// 且赞成严格多于反对。平票、无人投票或参与不足一律不通过。
563	// 通过比较法定人数剩余容量判断参与量，避免 for+against 上溢时回绕为负，
564	// 把已达标（乃至总权重恰好为 int64 上限）的提案误判为参与不足。
565	func votePasses(forWeight, againstWeight, quorum int64) bool {
566		if forWeight <= againstWeight {
567			return false // 平票或赞成更少都不通过；两侧非负，无票时同样落在这里
568		}
569		return forWeight >= quorum-againstWeight // 等价于 for+against >= quorum，且不做上溢加法
570	}
571	
572	// tallyVerdict 把通过条件映射为提案首次计票后的状态。
573	func tallyVerdict(passed bool) string {
574		if passed {
575			return "passed"
576		}
577		return "rejected"
578	}
579	
580	// countBallots 只按票据选择累加两侧权重，不做代表资格与票重核对
581	// （资格核对由 verifyBallots 负责）。任何一侧溢出 int64 都返回损坏错误。
582	func countBallots(ballots []storedBallot) (ballotCounts, error) {
583		var c ballotCounts
584		for _, b := range ballots {
585			if b.Support {
586				sum, ok := addInt64(c.forWeight, b.Weight)
587				if !ok {
588					return ballotCounts{}, errors.New("for-side ballot weights overflow int64")
589				}
590				c.forWeight = sum
591			} else {
592				sum, ok := addInt64(c.againstWeight, b.Weight)
593				if !ok {
594					return ballotCounts{}, errors.New("against-side ballot weights overflow int64")
595				}
596				c.againstWeight = sum
597			}
598		}
599		return c, nil
600	}
601	
602	// verifyBallots 依据成员名单与委托关系逐票核对并汇总：
603	// 代表必须是最终代表、不得重复、票重必须等于委托后归集到其名下的权重。
604	// 这些条件全部由打开状态文件时的严格校验保证，首次计票路径再核对一次，
605	// 使两条路径对“票重/代表是否可信”的判定使用同一份规则。
606	// 汇总只含实际投出的票；任一条件不符返回带具体原因的错误，
607	// 错误分类（ErrStateCorrupt）由调用方按自身路径统一包装。
608	func verifyBallots(id string, ballots []storedBallot, spec *proposalSpec) (ballotCounts, error) {
609		seen := map[string]bool{}
610		for i, b := range ballots {
611			if b.Representative == "" {
612				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d has empty representative", id, i)
613			}
614			if spec.headOf[b.Representative] != b.Representative {
615				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d: %q is not a final representative",
616					id, i, b.Representative)
617			}
618			if seen[b.Representative] {
619				return ballotCounts{}, fmt.Errorf("proposal %s has duplicate stored ballot for %q", id, b.Representative)
620			}
621			seen[b.Representative] = true
622			if b.Weight != spec.groupW[b.Representative] {
623				return ballotCounts{}, fmt.Errorf("proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
624					id, b.Representative, b.Weight, spec.groupW[b.Representative])
625			}
626		}
627		counts, err := countBallots(ballots)
628		if err != nil {
629			return ballotCounts{}, fmt.Errorf("proposal %s %v", id, err)
630		}
631		return counts, nil
632	}
633	
634	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
635	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
636	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
637	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
638	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
639		if voter == "" {
640			return nil, voteReject("voter id must not be empty")
641		}
642		commit, err := s.begin()
643		if err != nil {
644			return nil, err
645		}
646		defer commit()
647	
648		state, err := s.loadLocked()
649		if err != nil {
650			return nil, err
651		}
652		p, ok := state.VoteProposals[id]
653		if !ok {
654			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
655		}
656		spec, verr := specOf(p)
657		if verr != nil {
658			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
659		}
660		if _, member := spec.weights[voter]; !member {
661			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
662		}
663		if spec.headOf[voter] != voter {
664			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
665		}
666		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
667		// 改投另一选择报冲突，绝不静默覆盖。
668		for i := range p.Ballots {
669			if p.Ballots[i].Representative == voter {
670				if p.Ballots[i].Support != support {
671					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
672						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
673				}
674				b := p.Ballots[i]
675				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
676			}
677		}
678		if p.Tally != nil {
679			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
680		}
681		if now < p.StartAt || now >= p.Deadline {
682			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
683		}
684	
685		p.Ballots = append(p.Ballots, mustStoreBallot(voter, spec.groupW[voter], support, now))
686		if err := s.commitLocked(state); err != nil {
687			return nil, err
688		}
689		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
690	}
691	
692	func voteChoice(support bool) string {
693		if support {
694			return "for"
695		}
696		return "against"
697	}
698	
699	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
700	// 且赞成严格多于反对才通过。未投权重不计入参与量。
701	// 计票只确定状态，不转账；再次计票始终返回首次结论。
702	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
703		commit, err := s.begin()
704		if err != nil {
705			return nil, err
706		}
707		defer commit()
708	
709		state, err := s.loadLocked()
710		if err != nil {
711			return nil, err
712		}
713		p, ok := state.VoteProposals[id]
714		if !ok {
715			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
716		}
717		if p.Tally != nil {
718			return storedTallyResult(p), nil
719		}
720		if now < p.Deadline {
721			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
722		}
723	
724		spec, verr := specOf(p)
725		if verr != nil {
726			return nil, verr
727		}
728		// 计票规则只有一份：同一套“代表资格 + 票重 + 两侧汇总 + 法定人数/多数”
729		// 同时用于首次计票、打开文件时的重放校验与查询结论。
730		counts, verr := verifyBallots(id, p.Ballots, spec)
731		if verr != nil {
732			return nil, fmt.Errorf("%w: %v", ErrStateCorrupt, verr)
733		}
734		passed := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
735		p.Tally = &storedTally{ForWeight: counts.forWeight, AgainstWeight: counts.againstWeight, TalliedAt: now}
736		p.State = tallyVerdict(passed)
737		if err := s.commitLocked(state); err != nil {
738			return nil, err
739		}
740		return storedTallyResult(p), nil
741	}
742	
743	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
744	// Passed 由唯一的通过规则（votePasses）按保存权重重算：提案后续执行
745	// （executed）不改变首次结论，查询结论与首次计票结论因此始终一致。
746	// 调用方持有的状态均经过 validateState，两侧合计必然不超过合法总权重。
747	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
748		if p.Tally == nil {
749			return nil
750		}
751		c := ballotCounts{forWeight: p.Tally.ForWeight, againstWeight: p.Tally.AgainstWeight}
752		turnout, _ := c.turnout()
753		return &TallyResultView{
754			ForWeight:     c.forWeight,
755			AgainstWeight: c.againstWeight,
756			Turnout:       turnout,
757			Quorum:        p.Quorum,
758			Passed:        votePasses(c.forWeight, c.againstWeight, p.Quorum),
759			TalliedAt:     p.Tally.TalliedAt,
760		}
761	}
762	
763	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
764	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
765		state, err := s.readState()
766		if err != nil {
767			return nil, false, err
768		}
769		p, ok := state.VoteProposals[id]
770		if !ok {
771			return nil, false, nil
772		}
773		return voteProposalView(p), true, nil
774	}
775	
776	// VoteProposals 返回全部投票提案，按编号排序。
777	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
778		state, err := s.readState()
779		if err != nil {
780			return nil, err
781		}
782		return voteProposalViews(state), nil
783	}
784	
785	func voteProposalViews(state *storedState) []*VoteProposalView {
786		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
787		for _, p := range state.VoteProposals {
788			out = append(out, voteProposalView(p))
789		}
790		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
791		return out
792	}
793	
794	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
795		spec, err := specOf(p)
796		if err != nil {
797			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
798			panic("govflow: building view of corrupt proposal: " + err.Error())
799		}
800		members := make([]MemberView, 0, len(p.Members))
801		for _, m := range p.Members { // 保持成员提交顺序
802			mv := MemberView{
803				ID:       m.ID,
804				Weight:   m.Weight,
805				Path:     append([]string(nil), spec.pathOf[m.ID]...),
806				Delegate: spec.headOf[m.ID],
807			}
808			if to, ok := spec.delegate[m.ID]; ok {
809				mv.Direct = to
810			}
811			members = append(members, mv)
812		}
813		ballots := make([]BallotView, 0, len(p.Ballots))
814		for _, b := range p.Ballots { // 保持首次投票先后顺序
815			ballots = append(ballots, BallotView{
816				Representative: b.Representative,
817				Weight:         b.Weight,
818				Support:        b.Support,
819				VotedAt:        b.VotedAt,
820			})
821		}
822		v := &VoteProposalView{
823			ID:          p.ID,
824			Source:      "vote",
825			State:       p.State,
826			Quorum:      p.Quorum,
827			StartAt:     p.StartAt,
828			Deadline:    p.Deadline,
829			TimelockEnd: p.TimelockEnd,
830			Actions:     copyActions(p.Actions),
831			TotalWeight: spec.total,
832			Members:     members,
833			Ballots:     ballots,
834		}
835		if p.Tally != nil {
836			v.Tally = storedTallyResult(p)
837		}
838		return v
839	}
840	
841	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
842	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
843		in := &CreateVoteInput{
844			ID:          p.ID,
845			Quorum:      p.Quorum,
846			StartAt:     p.StartAt,
847			Deadline:    p.Deadline,
848			TimelockEnd: p.TimelockEnd,
849			Actions:     p.Actions,
850		}
851		in.Members = make([]VoteMember, len(p.Members))
852		for i, m := range p.Members {
853			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
854		}
855		in.Delegations = make([]Delegation, len(p.Delegations))
856		for i, d := range p.Delegations {
857			in.Delegations[i] = Delegation{From: d.From, To: d.To}
858		}
859		return validateProposalInput(in)
860	}
861	
862	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
863	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
864	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
865	func validateVoteProposals(state *storedState) error {
866		for key, p := range state.VoteProposals {
867			if p == nil {
868				return fmt.Errorf("voting proposal %q is empty", key)
869			}
870			if p.ID != key || p.ID == "" {
871				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
872			}
873			if _, collide := state.Proposals[p.ID]; collide {
874				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
875			}
876			switch p.State {
877			case "voting", "passed", "rejected", "executed":
878			default:
879				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
880			}
881			spec, err := specOf(p)
882			if err != nil {
883				return err
884			}
885	
886			// 每张已保存票据都必须明确写出 representative/weight/support/voted_at
887			// 且非 null、JSON 类型正确。先于代表资格与票重核对执行：字段缺损时直接判
888			// 整份文件损坏，绝不能把缺失的 support 默认成反对票、把缺失的 voted_at
889			// 默认成 0 后再继续给出查询或计票的部分结果。
890			for i := range p.Ballots {
891				if err := validateStoredBallot(p.ID, i, &p.Ballots[i]); err != nil {
892					return err
893				}
894			}
895	
896			// 票据明细的代表资格、重复票据、票重与两侧汇总，全部复用首次计票的
897			// verifyBallots：打开重放与首次计票对“票重/代表是否可信”只有一份判定，
898			// 汇总只含最终代表实际投出的票，未投成员权重不进入参与量。
899			counts, err := verifyBallots(p.ID, p.Ballots, spec)
900			if err != nil {
901				return err
902			}
903			// 首次投票时间必须落在窗口 [start, deadline) 内；此约束与票重汇总无关，
904			// 仍只属于打开时的明细校验。
905			for _, b := range p.Ballots {
906				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
907					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
908						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
909				}
910			}
911	
912			switch {
913			case p.Tally == nil:
914				if p.State != "voting" {
915					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
916				}
917			default:
918				if p.State == "voting" {
919					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
920				}
921				if p.Tally.TalliedAt < p.Deadline {
922					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
923				}
924				if p.Tally.ForWeight != counts.forWeight || p.Tally.AgainstWeight != counts.againstWeight {
925					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
926						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, counts.forWeight, counts.againstWeight)
927				}
928				// 通过条件同样只有一份：保存状态必须与票据重放出的结论一致，
929				// executed 是 passed 提案执行后的后继状态，仍对应“首次通过”。
930				passedNow := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
931				if passedNow != (p.State == "passed" || p.State == "executed") {
932					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
933				}
934			}
935		}
936		return nil
937	}
938

