247	func TestExecuteOverflow(t *testing.T) {
248		store, _ := openTempStore(t, math.MaxInt64)
249		defer store.Close()
250		// 两笔收款打到同一账户，合计超过 MaxInt64：第二条拒绝，且第一条不落盘。
251		mustRegister(t, store, "gip-over", 0, "transfer:a:9223372036854775000", "transfer:a:900")
252		_, err := store.Execute("gip-over", 0)
253		if !errors.Is(err, ErrExecutionRejected) || !strings.Contains(err.Error(), "overflow") {
254			t.Fatalf("overflow err=%v", err)
255		}
256		if bal, _ := store.TreasuryBalance(); bal != math.MaxInt64 {
257			t.Fatalf("treasury changed after overflow: %d", bal)
258		}
259		if bal, _ := store.Balance("a"); bal != 0 {
260			t.Fatalf("recipient changed after overflow: %d", bal)
261		}
262	}
