264	func TestReceiptOrderAndPersistence(t *testing.T) {
265		path := filepath.Join(t.TempDir(), "treasury.json")
266		store, err := InitTreasury(path, 1000)
267		if err != nil {
268			t.Fatal(err)
269		}
