384	// dupKeyInject 在 balances 对象里注入一个重复键。
385	func dupKeyInject(good []byte) []byte {
386		s := string(good)
387		marker := "\"balances\": {"
388		idx := strings.Index(s, marker)
389		if idx < 0 {
390			// 空 balances 被渲染成 {}，改为含重复键的对象。
391			s = strings.Replace(s, "\"balances\": {}", "\"balances\": {\"x\": 1, \"x\": 2}", 1)
392			return []byte(s)
393		}
394		insertAt := idx + len(marker)
395		return []byte(s[:insertAt] + "\"dup\": 1, " + s[insertAt:])
396	}
