676	func itoa(i int) string {
677		if i == 0 {
678			return "0"
679		}
680		neg := i < 0
681		if neg {
682			i = -i
683		}
684		var buf [20]byte
685		pos := len(buf)
686		for i > 0 {
687			pos--
688			buf[pos] = byte('0' + i%10)
689			i /= 10
690		}
691		if neg {
692			pos--
693			buf[pos] = '-'
694		}
695		return string(buf[pos:])
696	}
