827			}
828			assertReadable(t, raw)
829		})
830	
831		t.Run("escaped field names", func(t *testing.T) {
832			// 转义拼写与普通拼写表示同一个字段：单独出现正常识别。
833			raw := strings.Replace(string(good), `"version": 1`, `"\u0076ersion": 1`, 1)
834			raw = strings.Replace(raw, `"timelock_end"`, `"\u0074imelock_end"`, 1)
835			assertReadable(t, []byte(raw))
836		})
837	
838		// ---- 拒绝变体：每个都整文件拒绝，错误指出字段与所在记录，文件不被改写 ----
839	
840		mutate := func(fn func(root map[string]any)) []byte {
841			var clone map[string]any
842			if err := json.Unmarshal(good, &clone); err != nil {
843				t.Fatal(err)
844			}
845			fn(clone)
846			raw, err := json.MarshalIndent(clone, "", "  ")
847			if err != nil {
848				t.Fatal(err)
849			}
850			return append(raw, '\n')
851		}
852		rename := func(obj map[string]any, old, new string) {
853			v, ok := obj[old]
854			if !ok {
855				t.Fatalf("setup: key %q missing", old)
856			}
857			obj[new] = v
858			delete(obj, old)
859		}
860		proposal := func(root map[string]any) map[string]any {
861			return root["proposals"].(map[string]any)["GIP-1"].(map[string]any)
862		}
863		vote := func(root map[string]any) map[string]any {
864			return root["vote_proposals"].(map[string]any)["gip-vote"].(map[string]any)
865		}
866		receipt := func(root map[string]any) map[string]any {
867			return root["receipts"].([]any)[0].(map[string]any)
868		}
869	
870		rejected := map[string]struct {
871			raw  []byte
872			want []string // 错误原因应包含的片段（字段名与所在记录）
873		}{
874			"top-level Treasury": {
875				raw:  mutate(func(root map[string]any) { rename(root, "treasury", "Treasury") }),
876				want: []string{`"Treasury"`},
877			},
878			"proposal State": {
879				raw:  mutate(func(root map[string]any) { rename(proposal(root), "state", "State") }),
880				want: []string{`"State"`, `proposals["GIP-1"]`},
881			},
882			"proposal state and State twins": {
883				// 同一记录里同时放入 state 与 State，即使值相同也拒绝。
884				raw: mutate(func(root map[string]any) {
885					p := proposal(root)
886					p["State"] = p["state"]
887				}),
888				want: []string{`"State"`, `proposals["GIP-1"]`},
889			},
890			"ballot Support": {
891				raw: mutate(func(root map[string]any) {
892					rename(vote(root)["ballots"].([]any)[0].(map[string]any), "support", "Support")
893				}),
894				want: []string{`"Support"`, `vote_proposals["gip-vote"].ballots[0]`},
895			},
896			"tally Tallied_at": {
897				raw: mutate(func(root map[string]any) {
898					rename(vote(root)["tally"].(map[string]any), "tallied_at", "Tallied_at")
899				}),
900				want: []string{`"Tallied_at"`, ".tally"},
901			},
902			"receipt Proposal_ID": {
903				raw:  mutate(func(root map[string]any) { rename(receipt(root), "proposal_id", "Proposal_ID") }),
904				want: []string{`"Proposal_ID"`, "receipts[0]"},
905			},
906			"receipt balance Before": {
907				raw: mutate(func(root map[string]any) {
908					rename(receipt(root)["actions"].([]any)[0].(map[string]any)["treasury"].(map[string]any), "before", "Before")
909				}),
910				want: []string{`"Before"`, ".treasury"},
911			},
912			"member Weight": {
913				raw: mutate(func(root map[string]any) {
914					rename(vote(root)["members"].([]any)[0].(map[string]any), "weight", "Weight")
915				}),
916				want: []string{`"Weight"`, ".members[0]"},
917			},
918			"delegation From": {
919				raw: mutate(func(root map[string]any) {
920					rename(vote(root)["delegations"].([]any)[0].(map[string]any), "from", "From")
921				}),
922				want: []string{`"From"`, ".delegations[0]"},
923			},
924			"unknown field still rejected": {
925				raw:  mutate(func(root map[string]any) { proposal(root)["comment"] = "x" }),
926				want: []string{`"comment"`, `proposals["GIP-1"]`},
927			},
928			"escaped duplicate state": {
929				// 转义拼写与普通拼写是同一个键：同一对象出现两次属重复键。
930				raw: []byte(strings.Replace(string(good),
931					`"state": "executed"`, `"state": "executed", "st\u0061te": "executed"`, 1)),
932				want: []string{`duplicate key "state"`, `proposals["GIP-1"]`},
933			},
934		}
935		for name, tc := range rejected {
936			t.Run(name, func(t *testing.T) {
937				bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
938				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
939					t.Fatal(err)
940				}
941				s, err := Open(bad)
942				if !errors.Is(err, ErrStateCorrupt) {
943					if s != nil {
944						s.Close()
945					}
946					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
947				}
948				for _, want := range tc.want {
949					if !strings.Contains(err.Error(), want) {
950						t.Fatalf("error %q should mention %s", err.Error(), want)
951					}
952				}
953				// 损坏文件不被整理或写回。
954				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
955					t.Fatalf("corrupt file was modified")
956				}
957			})
958		}
959	
960		t.Run("reads after corruption", func(t *testing.T) {
961			// 打开后文件被改成非法字段：后续读取同样返回状态损坏，不提供部分信息。
962			p := filepath.Join(dir, "live.json")
963			if err := os.WriteFile(p, good, 0o600); err != nil {
964				t.Fatal(err)
965			}
966			s, err := Open(p)
967			if err != nil {
968				t.Fatal(err)
969			}
970			defer s.Close()
971			bad := mutate(func(root map[string]any) { rename(root, "treasury", "Treasury") })
972			if err := os.WriteFile(p, bad, 0o600); err != nil {
973				t.Fatal(err)
974			}
975			if _, err := s.BalanceSnapshot(); !errors.Is(err, ErrStateCorrupt) {
976				t.Fatalf("BalanceSnapshot on corrupted file err=%v, want ErrStateCorrupt", err)
977			}
978			if _, _, err := s.Proposal("GIP-1"); !errors.Is(err, ErrStateCorrupt) {
979				t.Fatalf("Proposal on corrupted file err=%v, want ErrStateCorrupt", err)
