61	func usage() {
62		fmt.Println(`usage: govflow <command> [flags]
63	
64	legacy commands:
65	  demo                         run the built-in voting demo
66	  version                      print the version
67	
68	local treasury commands:
69	  init       --state FILE --balance N
70	             create a new state file with the initial treasury balance
71	  register   --state FILE --id ID --timelock N --action A [--action A ...]
72	             register a passed proposal (idempotent; conflicting content errors)
73	  create-vote --state FILE --id ID --member ID:W [--member ID:W ...]
74	             [--delegate FROM:TO ...] --quorum N --start N --deadline N
75	             --timelock N [--action A ...]
76	             create a voting proposal with roster, weights, delegations and a
77	             voting window (idempotent on identical content; conflict otherwise)
78	  vote       --state FILE --id ID --voter M --choice for|against --now N
79	             cast one ballot as a final representative (repeat same choice is
80	             idempotent; changing choice errors)
81	  tally      --state FILE --id ID --now N
82	             tally a proposal at/after its deadline; repeat calls return the
83	             first result
84	  execute    --state FILE --id ID --now N
85	             execute a passed proposal whose timelock has elapsed
86	             (works for both registered and voted proposals)
87	  balances   --state FILE [--account ACCT]
88	             show treasury and recipient account balances
89	  proposal   --state FILE --id ID
90	             show one registered proposal
91	  proposals  --state FILE
92	             list all registered proposals by id
93	  receipt    --state FILE --id ID
94	             show the execution receipt of one proposal
95	  receipts   --state FILE
96	             list all receipts in the order they were successfully committed
97	
98	all treasury commands accept --json for machine-readable output.`)
99	}
