107	type commonFlags struct {
108		state  string
109		asJSON bool
110		fs     *flag.FlagSet
111	}
112	
113	func newCmdFlags(name string) *commonFlags {
114		fs := flag.NewFlagSet(name, flag.ContinueOnError)
115		fs.SetOutput(io.Discard)
116		cf := &commonFlags{fs: fs}
117		fs.StringVar(&cf.state, "state", "", "path to the local treasury state file")
118		fs.BoolVar(&cf.asJSON, "json", false, "emit machine-readable JSON")
119		return cf
120	}
121	
122	func (c *commonFlags) parse(args []string) {
123		if err := c.fs.Parse(args); err != nil {
124			fmt.Fprintf(os.Stderr, "usage error: %v\n", err)
125			c.fs.SetOutput(os.Stderr)
126			c.fs.Usage()
127			os.Exit(2)
128		}
129		if c.state == "" {
130			fmt.Fprintf(os.Stderr, "usage error: --state is required\n")
131			os.Exit(2)
132		}
133	}
