1	package govflow
2	
3	import (
4		"bytes"
5		"os"
6		"os/exec"
7		"path/filepath"
8		"regexp"
9		"strconv"
10		"strings"
11		"sync"
12		"testing"
13	)
14	
15	// buildCLI 将命令行编译到临时目录，供跨进程测试使用。仅使用标准库，离线可编译。
16	func buildCLI(t *testing.T) string {
17		t.Helper()
18		binary := filepath.Join(t.TempDir(), "govflow")
19		cmd := exec.Command("go", "build", "-o", binary, "./cmd/govflow")
20		// 测试工作目录为模块下的 govflow/，仓库根目录在上一层。
21		cmd.Dir = ".."
22		var out bytes.Buffer
23		cmd.Stderr = &out
24		if err := cmd.Run(); err != nil {
25			t.Fatalf("build cli: %v\n%s", err, out.String())
26		}
27		return binary
28	}
29	
30	func runCLI(t *testing.T, binary, state string, args ...string) (stdout, stderr string, code int) {
31		t.Helper()
32		// main 以第一个参数作为子命令，--state 必须位于子命令之后。
33		full := append([]string{args[0], "--state", state}, args[1:]...)
34		cmd := exec.Command(binary, full...)
35		var so, se bytes.Buffer
36		cmd.Stdout = &so
37		cmd.Stderr = &se
38		err := cmd.Run()
39		if ee, ok := err.(*exec.ExitError); ok {
40			code = ee.ExitCode()
41		} else if err != nil {
42			t.Fatalf("run cli %v: %v", args, err)
43		}
44		return so.String(), se.String(), code
45	}
46	
47	// TestCrossProcessSameProposal：多个进程同时执行同一提案，
48	// 只能有一份成功凭据；其余进程拿到同一份凭据（重试语义），不得二次扣款。
49	func TestCrossProcessSameProposal(t *testing.T) {
50		binary := buildCLI(t)
51		state := filepath.Join(t.TempDir(), "treasury.json")
52		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
53			t.Fatal("init failed")
54		}
55		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-1",
56			"--timelock", "100", "--action", "transfer:audits:250"); code != 0 {
57			t.Fatal("register failed")
58		}
59	
60		const n = 16
61		var wg sync.WaitGroup
62		codes := make([]int, n)
63		outputs := make([]string, n)
64		start := make(chan struct{})
65		for i := 0; i < n; i++ {
66			wg.Add(1)
67			go func(i int) {
68				defer wg.Done()
69				<-start
70				so, se, code := runCLI(t, binary, state, "execute", "--id", "gip-1",
71					"--now", strconv.Itoa(100+i), "--json")
72				codes[i] = code
73				outputs[i] = so + se
74			}(i)
75		}
76		close(start)
77		wg.Wait()
78	
79		for i, code := range codes {
80			if code != 0 {
81				t.Fatalf("process %d exited %d: %s", i, code, outputs[i])
82			}
83			// 每个进程看到的首次执行时间都必须是 100（最早请求未必胜出，但凭据唯一）。
84			if !strings.Contains(outputs[i], `"executed_at"`) {
85				t.Fatalf("process %d got no receipt: %s", i, outputs[i])
86			}
87		}
88		so, _, code := runCLI(t, binary, state, "receipts", "--json")
89		if code != 0 {
90			t.Fatal("receipts failed")
91		}
92		if strings.Count(so, `"proposal_id"`) != 1 {
93			t.Fatalf("expected exactly one receipt, got:\n%s", so)
94		}
95		if so2, _, _ := runCLI(t, binary, state, "balances", "--json"); !strings.Contains(so2, `"treasury": 750`) {
96			t.Fatalf("treasury must be 750 after single execution:\n%s", so2)
97		}
98	}
99	
100	// TestCrossProcessDifferentProposals：40 个进程各花 10，资金库只有 100，
101	// 必须恰好 10 个成功，且所有判断基于实际已提交余额。
102	func TestCrossProcessDifferentProposals(t *testing.T) {
103		binary := buildCLI(t)
104		state := filepath.Join(t.TempDir(), "treasury.json")
105		if _, _, code := runCLI(t, binary, state, "init", "--balance", "100"); code != 0 {
106			t.Fatal("init failed")
107		}
108		const n = 40
109		for i := 0; i < n; i++ {
110			if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-"+itoa(i),
111				"--timelock", "0", "--action", "transfer:acct:10"); code != 0 {
112				t.Fatalf("register %d failed", i)
113			}
114		}
115	
116		var wg sync.WaitGroup
117		successes := make(chan int, n)
118		failures := make(chan string, n)
119		start := make(chan struct{})
120		for i := 0; i < n; i++ {
121			wg.Add(1)
122			go func(i int) {
123				defer wg.Done()
124				<-start
125				_, se, code := runCLI(t, binary, state, "execute", "--id", "gip-"+itoa(i), "--now", "0")
126				if code == 0 {
127					successes <- 1
128				} else {
129					failures <- se
130				}
131			}(i)
132		}
133		close(start)
134		wg.Wait()
135		close(successes)
136		close(failures)
137		got := 0
138		for range successes {
139			got++
140		}
141		for msg := range failures {
142			if !strings.Contains(msg, "insufficient") {
143				t.Fatalf("unexpected failure reason: %s", msg)
144			}
145		}
146		if got != 10 {
147			t.Fatalf("cross-process successes=%d, want 10", got)
148		}
149	
150		so, _, _ := runCLI(t, binary, state, "balances", "--json")
151		if !strings.Contains(so, `"treasury": 0`) || !strings.Contains(so, `"acct": 100`) {
152			t.Fatalf("final balances wrong:\n%s", so)
153		}
154		so, _, _ = runCLI(t, binary, state, "receipts", "--json")
155		if strings.Count(so, `"proposal_id"`) != 10 {
156			t.Fatalf("expected 10 receipts, got:\n%s", so)
157		}
158	}
159	
160	// TestCrossProcessCrashConsistency：在并发执行期间反复 SIGKILL 进程，
161	// 状态文件在任何时刻都只能是整项执行前或执行后的完整状态。
162	func TestCrossProcessCrashConsistency(t *testing.T) {
163		binary := buildCLI(t)
164		state := filepath.Join(t.TempDir(), "treasury.json")
165		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000000"); code != 0 {
166			t.Fatal("init failed")
167		}
168		const n = 200
169		for i := 0; i < n; i++ {
170			if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-"+itoa(i),
171				"--timelock", "0", "--action", "transfer:a:1"); code != 0 {
172				t.Fatalf("register %d failed", i)
173			}
174		}
175	
176		// 启动后立刻 SIGKILL：杀死可能落在执行前、写盘前后任意位置。
177		var wg sync.WaitGroup
178		for i := 0; i < n; i++ {
179			wg.Add(1)
180			go func(i int) {
181				defer wg.Done()
182				cmd := exec.Command(binary, "execute", "--state", state, "--id", "gip-"+itoa(i), "--now", "0")
183				if err := cmd.Start(); err != nil {
184					t.Errorf("start %d: %v", i, err)
185					return
186				}
187				if i%3 == 0 {
188					_ = cmd.Process.Kill()
189				}
190				_ = cmd.Wait()
191			}(i)
192		}
193		wg.Wait()
194	
195		// 最终状态必须能严格打开：余额与凭据重放一致；被杀死的执行要么整体发生、要么整体未发生。
196		store, err := Open(state)
197		if err != nil {
198			t.Fatalf("state after crashes is unusable: %v", err)
199		}
200		defer store.Close()
201		treasury, err := store.TreasuryBalance()
202		if err != nil {
203			t.Fatal(err)
204		}
205		receipts, err := store.Receipts()
206		if err != nil {
207			t.Fatal(err)
208		}
209		if int64(len(receipts)) != 1000000-treasury {
210			t.Fatalf("invariant broken: receipts=%d treasury=%d", len(receipts), treasury)
211		}
212		// 每个 executed 提案恰好有凭据；无凭据的提案仍是 passed 且余额未变（重放校验已在 Open 中完成）。
213		executed := map[string]bool{}
214		for _, r := range receipts {
215			if executed[r.ProposalID] {
216				t.Fatalf("duplicate receipt for %s", r.ProposalID)
217			}
218			executed[r.ProposalID] = true
219		}
220		proposals, err := store.Proposals()
221		if err != nil {
222			t.Fatal(err)
223		}
224		for _, p := range proposals {
225			if p.State == "executed" && !executed[p.ID] {
226				t.Fatalf("proposal %s executed without receipt", p.ID)
227			}
228			if p.State == "passed" && executed[p.ID] {
229				t.Fatalf("proposal %s passed but has receipt", p.ID)
230			}
231		}
232	}
233	
234	// TestCrossProcessVotingLifecycle：通过 CLI 跨进程完成创建→委托投票→计票→执行，
235	// 并验证重复创建/投票/计票的幂等与冲突语义。
236	func TestCrossProcessVotingLifecycle(t *testing.T) {
237		binary := buildCLI(t)
238		state := filepath.Join(t.TempDir(), "treasury.json")
239		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
240			t.Fatal("init failed")
241		}
242		create := []string{"create-vote", "--id", "gip-vote-1",
243			"--member", "alice:300", "--member", "bob:200", "--member", "carol:100", "--member", "dave:400",
244			"--delegate", "bob:alice", "--delegate", "carol:alice",
245			"--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300",
246			"--action", "transfer:audits:100"}
247		if _, se, code := runCLI(t, binary, state, create...); code != 0 {
248			t.Fatalf("create-vote failed: %s", se)
249		}
250		// 成员与委托换序的完全相同重试：成功且不改动状态。
251		retry := []string{"create-vote", "--id", "gip-vote-1",
252			"--member", "dave:400", "--member", "carol:100", "--member", "bob:200", "--member", "alice:300",
253			"--delegate", "carol:alice", "--delegate", "bob:alice",
254			"--quorum", "600", "--start", "100", "--deadline", "200", "--timelock", "300",
255			"--action", "transfer:audits:100"}
256		if _, se, code := runCLI(t, binary, state, retry...); code != 0 {
257			t.Fatalf("identical create retry should succeed: %s", se)
258		}
259		// 内容不同的重试冲突（多一个动作，动作按原文及顺序比较）。
260		conflict := append(append([]string{}, create...), "--action", "transfer:legal:1")
261		if _, _, code := runCLI(t, binary, state, conflict...); code != 1 {
262			t.Fatalf("conflicting create should exit 1, got %d", code)
263		}
264		// register 不能占用投票提案编号。
265		if _, se, code := runCLI(t, binary, state, "register", "--id", "gip-vote-1",
266			"--timelock", "300", "--action", "transfer:audits:100"); code != 1 {
267			t.Fatalf("register over voting id should fail: %s", se)
268		}
269	
270		// 委托出去的成员投票被拒；非名单成员被拒。
271		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
272			"--voter", "bob", "--choice", "for", "--now", "150"); code != 1 || !strings.Contains(se, "delegated") {
273			t.Fatalf("delegated member vote code=%d: %s", code, se)
274		}
275		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
276			"--voter", "ghost", "--choice", "for", "--now", "150"); code != 1 || !strings.Contains(se, "not on the member roster") {
277			t.Fatalf("non-member vote code=%d: %s", code, se)
278		}
279	
280		// 代表 alice（归集 600）赞成；相同选择跨进程重试返回首次时间。
281		if so, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
282			"--voter", "alice", "--choice", "for", "--now", "120", "--json"); code != 0 ||
283			!strings.Contains(so, `"weight": 600`) {
284			t.Fatalf("alice vote code=%d so=%s se=%s", code, so, se)
285		}
286		if so, _, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
287			"--voter", "alice", "--choice", "for", "--now", "180", "--json"); code != 0 ||
288			!strings.Contains(so, `"voted_at": 120`) {
289			t.Fatalf("identical vote retry must return first record: %s", so)
290		}
291		// 改投冲突。
292		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
293			"--voter", "alice", "--choice", "against", "--now", "120"); code != 1 ||
294			!strings.Contains(se, "changing the vote") {
295			t.Fatalf("change vote code=%d: %s", code, se)
296		}
297	
298		// 截止前计票拒绝。
299		if _, se, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1", "--now", "199"); code != 1 ||
300			!strings.Contains(se, "still open") {
301			t.Fatalf("early tally code=%d: %s", code, se)
302		}
303		// 截止时刻计票：600 赞成、0 反对、达到法定人数 => passed。
304		if so, se, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
305			"--now", "200", "--json"); code != 0 || !strings.Contains(so, `"passed": true`) {
306			t.Fatalf("tally code=%d so=%s se=%s", code, so, se)
307		}
308		// 计票后窗口内新票也拒绝。
309		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
310			"--voter", "dave", "--choice", "against", "--now", "150"); code != 1 ||
311			!strings.Contains(se, "already been tallied") {
312			t.Fatalf("post-tally vote code=%d: %s", code, se)
313		}
314		// 再次计票返回首次时间。
315		if so, _, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
316			"--now", "999", "--json"); code != 0 || !strings.Contains(so, `"tallied_at": 200`) {
317			t.Fatalf("repeat tally: %s", so)
318		}
319	
320		// 通过后直接由 execute 执行，无需再登记；时间锁未到拒绝。
321		if _, _, code := runCLI(t, binary, state, "execute", "--id", "gip-vote-1", "--now", "299"); code != 1 {
322			t.Fatalf("execute before timelock should fail")
323		}
324		if _, _, code := runCLI(t, binary, state, "execute", "--id", "gip-vote-1", "--now", "300"); code != 0 {
325			t.Fatalf("execute voted proposal failed")
326		}
327		if so, _, _ := runCLI(t, binary, state, "balances", "--json"); !strings.Contains(so, `"treasury": 900`) ||
328			!strings.Contains(so, `"audits": 100`) {
329			t.Fatalf("balances after voted execution:\n%s", so)
330		}
331		// 已执行提案不退回通过：再次执行返回首次凭据。
332		if so, _, _ := runCLI(t, binary, state, "execute", "--id", "gip-vote-1",
333			"--now", "9999", "--json"); !strings.Contains(so, `"executed_at": 300`) {
334			t.Fatalf("re-execute should return first receipt: %s", so)
335		}
336		// 查询包含逐票明细、委托路径与已执行状态。
337		so, _, _ := runCLI(t, binary, state, "proposal", "--id", "gip-vote-1", "--json")
338		if !strings.Contains(so, `"state": "executed"`) ||
339			!strings.Contains(so, `"representative": "alice"`) ||
340			!pathJSONRe.MatchString(so) {
341			t.Fatalf("proposal query missing delegation path/ballot/state:\n%s", so)
342		}
343	}
344	
345	var pathJSONRe = regexp.MustCompile(`"path": \[\s+"bob",\s+"alice"\s+\]`)
