434	// TestCLIRejectsCaseVariantField：固定字段名的大小写变体让整个状态文件被拒绝，
435	// 命令行将原因（含问题字段）写到标准错误并以状态码 1 退出，文件不被改写。
436	func TestCLIRejectsCaseVariantField(t *testing.T) {
