503		// 文本与 JSON 查询采用同一判定：均为退出码 1、原因在 stderr、stdout 为空。
504		for _, args := range [][]string{
505			{"proposal", "--id", "gip-cli"},
506			{"proposal", "--id", "gip-cli", "--json"},
507			{"proposals"},
