527			})
528		}
529		if got, err := os.ReadFile(state); err != nil || string(got) != corrupt {
530			t.Fatalf("corrupt file was modified or rewritten")
531		}
532	
533		// 对照：明确写出的 false 反对票与 0 投票时间是合法值，文本与 JSON 都能查询。
534		legal := filepath.Join(dir, "legal.json")
535		legalRaw := `{
